-- gen624: 18 zone cambiate, 37 tessere
-- 3867679ff319995d9024e18abc4b2425 (1063404) → cd1d92142ea7e891be2e35266859cb50 (1069982)

  on conflict (key) do update set value=excluded.value;


-- il cancello, PRIMA di scrivere
select md5(string_agg(value, '' order by key)) as md5_ricomposto,
       length(string_agg(value, '' order by key)) as len_ricomposto,
       md5(string_agg(value, '' order by key)) = 'cd1d92142ea7e891be2e35266859cb50' as combacia
from kv_store where key like 'tmp:gen624:p%';

update kv_store set value = (select string_agg(value, '' order by key) from kv_store where key like 'tmp:gen624:p%')
where key='app:jsx:src'
  and md5(value) = '3867679ff319995d9024e18abc4b2425'
  and (select md5(string_agg(value, '' order by key)) from kv_store where key like 'tmp:gen624:p%') = 'cd1d92142ea7e891be2e35266859cb50';

update kv_store set value = '{"len":1069982,"ver":"gen-6.24"}'
where key='app:jsx:meta'
  and (select md5(value) from kv_store where key='app:jsx:src') = 'cd1d92142ea7e891be2e35266859cb50';

delete from kv_store where key like 'tmp:gen624:p%';
